</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <vector>
#include <iostream>
#include <algorithm>

int compute_span(const std::vector<int>& array, int start_index, int max_time) {
    int length = 1;
    for (int k = start_index + 1; k < (int)array.size(); ++k) {
        if (array[k] - array[start_index] > max_time)
            break;
        ++length;
    }
    return length;
}

int main() {
    std::vector<int> values;
    int count, max_time;
    std::cin >> count;
    for (int i = 0; i < count; ++i) {
        int val;
        std::cin >> val;
        values.push_back(val);
    }
    std::cin >> max_time;
    std::sort(values.begin(), values.end());
    int max_length = 0;
    for (int i = 0; i < (int)values.size(); ++i) {
        int current_span = compute_span(values, i, max_time);
        if (current_span > max_length)
            max_length = current_span;
    }
    std::cout << max_length << "\n";
}
